const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("transfer-items: is atomic - an item not owned by the source leaves everything untouched", async () => {
  const { base, close } = startServer();
  try {
    const from = await api(base, "POST", "/api/warehouses", { name: "A", location: "NYC" });
    const to = await api(base, "POST", "/api/warehouses", { name: "B", location: "LA" });
    const other = await api(base, "POST", "/api/warehouses", { name: "C", location: "SF" });

    const item1 = await api(base, "POST", "/api/items", {
      sku: "A1",
      name: "Widget",
      warehouseId: from.json.id,
      quantity: 5,
    });
    const foreignItem = await api(base, "POST", "/api/items", {
      sku: "C1",
      name: "Gadget",
      warehouseId: other.json.id,
      quantity: 1,
    });

    const resp = await api(base, "POST", `/api/warehouses/${from.json.id}/transfer-items`, {
      toWarehouseId: to.json.id,
      itemIds: [item1.json.id, foreignItem.json.id],
    });
    assert.strictEqual(resp.status, 400);

    const check1 = await api(base, "GET", `/api/items/${item1.json.id}`);
    assert.strictEqual(check1.json.warehouseId, from.json.id);
  } finally {
    await close();
  }
});

test("transfer-items: moves all items when every id belongs to the source", async () => {
  const { base, close } = startServer();
  try {
    const from = await api(base, "POST", "/api/warehouses", { name: "A", location: "NYC" });
    const to = await api(base, "POST", "/api/warehouses", { name: "B", location: "LA" });

    const item1 = await api(base, "POST", "/api/items", {
      sku: "A1",
      name: "Widget",
      warehouseId: from.json.id,
      quantity: 5,
    });

    const resp = await api(base, "POST", `/api/warehouses/${from.json.id}/transfer-items`, {
      toWarehouseId: to.json.id,
      itemIds: [item1.json.id],
    });
    assert.strictEqual(resp.status, 200);

    const check1 = await api(base, "GET", `/api/items/${item1.json.id}`);
    assert.strictEqual(check1.json.warehouseId, to.json.id);
  } finally {
    await close();
  }
});

