const express = require("express");
const store = require("../store/warehouseStore");

const warehousesRouter = express.Router();

warehousesRouter.post("/", (req, res) => {
  const body = req.body ?? {};
  const name = typeof body.name === "string" ? body.name.trim() : "";
  const location = typeof body.location === "string" ? body.location.trim() : "";
  if (name.length === 0) {
    res.status(400).json({ error: "name is required" });
    return;
  }
  if (location.length === 0) {
    res.status(400).json({ error: "location is required" });
    return;
  }
  let maxCapacity = null;
  if (body.maxCapacity !== undefined && body.maxCapacity !== null) {
    maxCapacity = Number(body.maxCapacity);
    if (!Number.isInteger(maxCapacity) || maxCapacity < 0) {
      res.status(400).json({ error: "maxCapacity must be a non-negative integer" });
      return;
    }
  }
  const warehouse = store.createWarehouse({ name, location, maxCapacity });
  res.status(201).json(warehouse);
});

warehousesRouter.get("/", (_req, res) => {
  res.status(200).json(store.listWarehouses());
});

warehousesRouter.get("/:id", (req, res) => {
  const warehouse = store.getWarehouse(Number(req.params.id));
  if (!warehouse) {
    res.status(404).json({ error: "warehouse not found" });
    return;
  }
  res.status(200).json(warehouse);
});

warehousesRouter.post("/:fromId/transfer-items", (req, res) => {
  const fromId = Number(req.params.fromId);
  const fromWarehouse = store.getWarehouse(fromId);
  if (fromWarehouse === undefined) {
    res.status(404).json({ error: "source warehouse not found" });
    return;
  }

  const body = req.body ?? {};
  const toId = Number(body.toWarehouseId);
  const toWarehouse = Number.isInteger(toId) ? store.getWarehouse(toId) : undefined;
  if (toWarehouse === undefined) {
    res.status(400).json({ error: "toWarehouseId must reference an existing warehouse" });
    return;
  }
  if (!Array.isArray(body.itemIds) || body.itemIds.length === 0) {
    res.status(400).json({ error: "itemIds must be a non-empty array" });
    return;
  }

  const itemStore = require("../store/itemStore");
  const items = [];
  for (const rawId of body.itemIds) {
    const itemId = Number(rawId);
    const item = itemStore.getItem(itemId);
    if (item === undefined || item.warehouseId !== fromId) {
      res.status(400).json({ error: `item ${rawId} does not belong to the source warehouse` });
      return;
    }
    items.push(item);
  }

  if (toWarehouse.maxCapacity !== null && toWarehouse.maxCapacity !== undefined) {
    const destinationTotal = itemStore
      .listItems()
      .filter((item) => item.warehouseId === toId)
      .reduce((sum, item) => sum + item.quantity, 0);
    const movingTotal = items.reduce((sum, item) => sum + item.quantity, 0);
    if (destinationTotal + movingTotal > toWarehouse.maxCapacity) {
      res.status(400).json({ error: "transfer would exceed destination warehouse maxCapacity" });
      return;
    }
  }

  for (const item of items) {
    itemStore.updateItem(item.id, { warehouseId: toId });
  }
  res.status(200).json(items.map((item) => itemStore.getItem(item.id)));
});

module.exports = { warehousesRouter };

